    description: "Android manifest with PDF intent filters (ACTION_VIEW, ACTION_SEND) and permissions",
    content: "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n\n    <application\n        android:allowBackup=\"true\"\n        android:icon=\"@mipmap/ic_launcher\"\n        android:label=\"@string/app_name\"\n        android:roundIcon=\"@mipmap/ic_launcher\"\n        android:supportsRtl=\"true\"\n        android:theme=\"@style/Theme.PageNest\">\n        \n        <activity\n            android:name=\".MainActivity\"\n            android:exported=\"true\"\n            android:launchMode=\"singleTask\"\n            android:configChanges=\"orientation|screenSize|screenLayout|keyboardHidden\"\n            android:theme=\"@style/Theme.PageNest\">\n            \n            <!-- Main launcher entry point -->\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n            \n            <!-- 1. ACTION_VIEW for PDF documents (content:// scheme: Gmail attachments, Downloads, Drive, File Managers) -->\n            <intent-filter>\n                <action android:name=\"android.intent.action.VIEW\" />\n                <category android:name=\"android.intent.category.DEFAULT\" />\n                <category android:name=\"android.intent.category.BROWSABLE\" />\n                <data android:scheme=\"content\" />\n                <data android:mimeType=\"application/pdf\" />\n            </intent-filter>\n\n            <!-- 2. ACTION_VIEW for local PDF files (file:// scheme) -->\n            <intent-filter>\n                <action android:name=\"android.intent.action.VIEW\" />\n                <category android:name=\"android.intent.category.DEFAULT\" />\n                <category android:name=\"android.intent.category.BROWSABLE\" />\n                <data android:scheme=\"file\" />\n                <data android:mimeType=\"application/pdf\" />\n            </intent-filter>\n\n            <!-- 3. ACTION_VIEW for generic application/pdf intents without explicit scheme -->\n            <intent-filter>\n                <action android:name=\"android.intent.action.VIEW\" />\n                <category android:name=\"android.intent.category.DEFAULT\" />\n                <category android:name=\"android.intent.category.BROWSABLE\" />\n                <data android:mimeType=\"application/pdf\" />\n            </intent-filter>\n\n            <!-- 4. ACTION_VIEW pattern matching for browser downloads with .pdf extension -->\n            <intent-filter>\n                <action android:name=\"android.intent.action.VIEW\" />\n                <category android:name=\"android.intent.category.DEFAULT\" />\n                <category android:name=\"android.intent.category.BROWSABLE\" />\n                <data android:scheme=\"content\" android:host=\"*\" android:pathPattern=\".*\\\\.pdf\" />\n                <data android:scheme=\"file\" android:host=\"*\" android:pathPattern=\".*\\\\.pdf\" />\n            </intent-filter>\n\n            <!-- 5. ACTION_SEND: Single PDF document shared from other apps -->\n            <intent-filter>\n                <action android:name=\"android.intent.action.SEND\" />\n                <category android:name=\"android.intent.category.DEFAULT\" />\n                <data android:mimeType=\"application/pdf\" />\n            </intent-filter>\n\n            <!-- 6. ACTION_SEND_MULTIPLE: Multiple PDF documents shared from other apps -->\n            <intent-filter>\n                <action android:name=\"android.intent.action.SEND_MULTIPLE\" />\n                <category android:name=\"android.intent.category.DEFAULT\" />\n                <data android:mimeType=\"application/pdf\" />\n            </intent-filter>\n        </activity>\n    </application>\n\n</manifest>\n",
